from math import dist

def read(name):
    p = []
    for line in open(name):
        x, y = line.replace(',', '.').split()
        p.append((float(x), float(y)))
    return p

def clusters(p, r):
    p = p[:]
    res = []
    while p:
        c = [p.pop()]
        for a in c:
            near = [b for b in p if dist(a, b) < r]
            for b in near:
                p.remove(b)
            c += near
        res.append(c)
    return res

def center(c):
    return min(c, key=lambda a: sum(dist(a, b) for b in c))

cs = [center(c) for c in clusters(read('27a.txt'), 1)]
px = sum(x for x, y in cs) / len(cs)
py = sum(y for x, y in cs) / len(cs)
print(int(px * 10000), int(py * 10000))

