from math import dist

def read(name):
    p = []
    for line in open(name):
        x, y = line.replace(',', '.').split()
        p.append((float(x), float(y)))
    return p

def clusters(p, r):
    p = p[:]
    res = []
    while p:
        c = [p.pop()]
        for a in c:
            near = [b for b in p if dist(a, b) < r]
            for b in near:
                p.remove(b)
            c += near
        res.append(c)
    return res

def center(c):
    return min(c, key=lambda a: sum(dist(a, b) for b in c))

far = []
for c in clusters(read('27b.txt'), 1):
    z = center(c)
    far.append(max(dist(z, a) for a in c))
print(int(min(far) * 10000), int(max(far) * 10000))
